def find_permutation(n, k):
    p = list(range(1, n + 1))
    distinct_diffs = set()

    for i in range(n - 1):
        distinct_diffs.add(abs(p[i] - p[i + 1]))

    while len(distinct_diffs) < k:
        for i in range(n - 1):
            if abs(p[i] - p[i + 1]) not in distinct_diffs:
                distinct_diffs.add(abs(p[i] - p[i + 1]))
                break
        else:
            # If we have checked all possible pairs and still need more distinct differences,
            # we need to swap elements to create new differences.
            for i in range(n - 1):
                for j in range(i + 1, n):
                    if abs(p[i] - p[j]) not in distinct_diffs:
                        p[i], p[j] = p[j], p[i]
                        distinct_diffs.add(abs(p[i] - p[j]))
                        break
                if len(distinct_diffs) == k:
                    break
            break

    return p

